def transpose(text):
    rows = text.split("\n")
    width = max((len(r) for r in rows), default=0)
    if width == 0:
        return ""
    result = []
    for j in range(width):
        chars = []
        for r in rows:
            if j < len(r):
                chars.append(r[j])
            else:
                chars.append(" ")
        line = "".join(chars)
        # strip trailing padding (positions beyond the original row length)
        k = len(line)
        while k > 0 and j >= len(rows[k - 1]):
            k -= 1
        result.append(line[:k])
    return "\n".join(result)
